import itertools

def get_valid_T(N):
    valid_T = []

    def find_paths(current_path):
        # Add the current path (if non-empty)
        if current_path:
            valid_T.append(tuple(current_path))

        last_t = current_path[-1]

        # Try extending the path
        # Next element t_next must be > last_t and <= last_t + 2
        for t_next in range(last_t + 1, min(N + 1, last_t + 3)):
            find_paths(current_path + [t_next])

    # Start paths from every possible index 1 to N
    for start_t in range(1, N + 1):
        find_paths([start_t])

    # Remove duplicates if any, although the structure should prevent it if called correctly
    return set(valid_T)

def check_N(N):
    valid_T = get_valid_T(N)

    if N == 0:
        return 0

    min_max_sum = float('inf')

    # Iterate over all 2^N sequences A
    sequences = []
    for i in range(2**N):
        A = []
        for j in range(N):
            # 1 if bit j is 1, -1 if bit j is 0
            A.append(1 if (i >> j) & 1 else -1)
        sequences.append(A)

    for A in sequences:
        max_abs_sum = 0
        for T in valid_T:
            current_sum = sum(A[i-1] for i in T)
            max_abs_sum = max(max_abs_sum, abs(current_sum))

        min_max_sum = min(min_max_sum, max_abs_sum)

    return min_max_sum

# Test N=3, 4, 5, 6
results = {}
for N in [3, 4, 5, 6]:
    print(f"N={N} Minimum of maximum sums: {check_N(N)}")
    results[N] = check_N(N)

print("\nResults dictionary:", results)
